-- Compliance Certification Center §8.8 — verification source config table + seed.

CREATE TABLE IF NOT EXISTS plenum_cafm.compliance_verification_sources
(
    certificate_type_code  varchar(80)  NOT NULL,
    cert_scope             varchar(20)  NOT NULL,
    verification_group     varchar(40)  NOT NULL,
    channel                varchar(20)  NOT NULL,
    register               varchar(120),
    source_url             text,
    api_available          varchar(12)  NOT NULL,
    refresh_cadence        varchar(20),
    notes                  text,
    code_aliases           jsonb        NOT NULL DEFAULT '[]'::jsonb,
    country_code           varchar(8)   NOT NULL DEFAULT 'UK',
    created_at             timestamptz  NOT NULL DEFAULT now(),
    updated_at             timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT compliance_verification_sources_pkey
        PRIMARY KEY (certificate_type_code, country_code)
);

ON CONFLICT (certificate_type_code, country_code) DO UPDATE SET
    cert_scope = EXCLUDED.cert_scope,
    verification_group = EXCLUDED.verification_group,
    channel = EXCLUDED.channel,
    register = EXCLUDED.register,
    source_url = EXCLUDED.source_url,
    api_available = EXCLUDED.api_available,
    refresh_cadence = EXCLUDED.refresh_cadence,
    notes = EXCLUDED.notes,
    code_aliases = EXCLUDED.code_aliases,
    updated_at = now();
